import sys, random, json, importlib.util
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

def minimal_states(req):
    out = json.loads(m.process(json.dumps(req)))
    if out.get('ok'):
        return len(out['dfa']['next']), len(out['dfa']['next'][0]) if out['dfa']['next'] else 0
    return out

rng = random.Random(17)
best = 0; bestreq=None
for asize in (3,4,6,8):
    toks = ['t%d'%i for i in range(asize)]
    for trial in range(15):
        atoms=[]; seen=set()
        while len(atoms)<10:
            p = tuple(rng.choice(toks) for _ in range(rng.randint(4,16)))
            op = rng.choice(['endswith','contains','match','startswith'])
            if (op,p) not in seen: seen.add((op,p)); atoms.append((op,p))
        req = {'services': toks,
               'rules': [{'action':'allow','when':{'op':'and','args':[{'op':'not','arg':{'op':op,'path':list(p)}} for (op,p) in atoms]}},
                         {'action':'drop','when':{'op':'or','args':[{'op':op,'path':list(p)} for (op,p) in atoms[:3]]}}],
               'queries': []}
        r = minimal_states(req)
        if isinstance(r, tuple):
            if r[0] > best:
                best, bestreq = r[0], req
                print('alphabet', asize, 'minimal states', r[0])
        else:
            pass
print('BEST minimal states', best)
if bestreq: json.dump(bestreq, open('/workspace/tests/big_min.json','w'))
EOF
